data.query:
query Query($l: ShipmentLineWhereInput, $a: AndonRequestWhereInput) {
  line:shipmentLine(where: $l) {
    edges {
      node {
        id
        loadedQuantity {
          value
          unitId
        }
        quantity {
          value
          unitId
        }
        shippedQuantity {
          value
          unitId
        }
        stagedQuantity {
          value
          unitId
        }
        shipment {
          shipmentStageId
        }
        shipmentId
        shipmentLineStageId
        productId
        shipmentLineInventory {
          edges {
            node {
              inventory {
                id
                quantity {
                  value
                  unitId
                }
                inventoryStatusId
              }
            }
          }
        }
        andonRequests(where:$a) {
          edges {
            node {
              id
              quantity {
                value
                unitId
              }
              inventory {
                edges {node{
                  id 
                  complete
                  loaded
                  inventory {
                    quantity {value unitId}
                  }
                }}
              }
              andonStageId
              destinationLocationId
            }
          }
        }
      }
    }
  }
}

query Inventory( 
  $whereI:InventoryWhereInput!
) {

	inventory(where:$whereI, first:1) {
    edges {node {
      id
      number
      productId
      productStrategyProcess{
        id

        productStrategy{
          product {id name}
        }
      }
      location {
        id
        name
      }
      quantity {
        value
        unit {id code}
      }
      inventoryStatus {
        splitPrevent

        id
      }
      masterInventory {
        id
        active
        allowUnload
      }
      lotId
      workOrderProcessId
      workOrderId
      receiptLineId
      supplierId
      packagingMaterialId
      kanbanCardId
      inventoryTypeId
      grossWeight
      netWeight
      tareWeight
      theoreticalWeight
      weightUnitId

      andonRequestInventory {total}
      shipmentLineInventories {total}
    }}
  }
}

query Query($where: InventoryWhereInput) {
  inventory(where: $where, first: 1) {
    edges {
      node {
        number
      }
    }
  }
}

query Query($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        quantity {
          value unitId
        }
        location {
          id
          name
        }
        product {id name}
        productStrategyProcessId
      }
    }
  }
}

